package com.clinic.appointment;
import org.springframework.boot.SpringApplication;import org.springframework.boot.autoconfigure.SpringBootApplication;import org.springframework.context.annotation.Bean;import org.springframework.http.client.SimpleClientHttpRequestFactory;import org.springframework.scheduling.annotation.EnableScheduling;import org.springframework.web.client.RestClient;
@SpringBootApplication @EnableScheduling public class AppointmentServiceApplication{public static void main(String[]a){SpringApplication.run(AppointmentServiceApplication.class,a);}@Bean RestClient.Builder restClientBuilder(){SimpleClientHttpRequestFactory f=new SimpleClientHttpRequestFactory();f.setConnectTimeout(2000);f.setReadTimeout(15000);return RestClient.builder().requestFactory(f);}}
